mapper.select:
select

from sys_evaluate
where is_delete = 0 and indent_number = #{orderId}

select count(1) from sys_evaluate se LEFT JOIN tb_orders to1 ON se.indent_number = to1.order_num LEFT JOIN tb_user tu on se.user_id = tu.user_id where se.is_delete = 0 and se.feedback_status = 1 and to1.is_evaluate = 1 and se.recycle_status = 0 and to1.seller_id = #{byUserId}
AND se.indent_number IN
#{orderNumber}

SELECT se.evaluate_id, se.user_id, se.indent_number, se.evaluate_message, se.satisfaction_flag, se.create_time, se.evaluate_img, se.is_delete, tu.avatar as avatar, tu.user_name as userName FROM sys_evaluate se LEFT JOIN tb_orders to1 ON se.indent_number = to1.order_num LEFT JOIN tb_user tu ON se.user_id = tu.user_id WHERE se.is_delete = 0 AND se.feedback_status = 1 AND to1.is_evaluate = 1 AND se.recycle_status = 0 AND to1.seller_id = #{params.byUserId}
AND se.user_id IN
#{id}
ORDER BY se.create_time DESC LIMIT #{params.limit} OFFSET #{params.page}
